    q4491: { h: "8b9c7a240068", text: "Listening to a customer's request for a pot and giving the clay its shape: would you enjoy it?" },
    q4492: { h: "8b87f9bd789b", text: "Looking at the size of a customer's shoe and telling the repair price: would you like it?" },
    q4493: { h: "5db0ce001a69", text: "Counting a customer's clothes and settling the washing price: would it suit you?" },
    q4494: { h: "279304122cdf", text: "Listening to what a customer likes and cutting their hair: would you enjoy it?" },
    q4495: { h: "f6c5b3c1cd57", text: "Weighing a customer's jewellery and settling the pawn amount: would you like it?" },
    q4496: { h: "b5f146c8660c", text: "Letting a customer feel khadi cloth, telling its softness and selling: would it suit you?" },
    q4497: { h: "20e050c201cf", text: "Listening to what a devotee likes and showing the form of the idol: would you enjoy it?" },
    q5408: { h: "ee54ec2c3028", text: "The queue in the office grew long: would improving the arrangements feel good?" },
    q5409: { h: "1c1eb3d9d8e1", text: "Cleaning fell behind in the area: would you enjoy improving the arrangements?" },
