    q7308: { h: "041d26b65320", text: "Not giving the public's private details to anyone without need: would you enjoy this watch on details?" },
    q7309: { h: "59f499493f78", text: "A ring of lights at night around the open pits of the lane: does this ring of lights appeal to you?" },
    q7310: { h: "8f08265995aa", text: "Keeping separate passwords for each of the linked government services: would you keep up this rule of separate passwords?" },
    q7311: { h: "a1867cfd7c83", text: "Keeping people's income details sealed behind your lips: would you accept this sealing of lips?" },
    q7312: { h: "3f7b9fc2aed0", text: "Keeping the confidential purchase rate sealed until the bids are opened: will you keep this guard on the seal?" },
    q7313: { h: "6c80141629f5", text: "Anyone's name and address kept separate from the tally in a count: would you enjoy this rule of separation?" },
    q7314: { h: "fb20821ded6a", text: "The private matters of each home must not reach any outsider: does this silence appeal to you?" },
    q7315: { h: "875f6d4498ce", text: "Confidential policy papers must not leak out before the fixed time: would you keep up this silence?" },
    q7316: { h: "be35df2b89a4", text: "A decision only after matching the latest book of rules and laws in two places: would you accept this patience of matching?" },
    q7317: { h: "f600f2540581", text: "A safety copy of public data in another machine: will you keep this safety copy?" },
    q7318: { h: "1beda911540e", text: "Keeping the donation account book clean, with every paisa entered: would you enjoy this clean entry?" },
    q7319: { h: "d5dda628ba1b", text: "Not telling anyone the private matters of those who receive help: does this silence appeal to you?" },
    q7320: { h: "b0d4f24dfe07", text: "Not putting up any beneficiary's picture anywhere without permission: would you keep up this rule of permission?" },
    q7321: { h: "8b227096acf6", text: "Donated money in a separate, secure account with its accounts: would you accept this rule of a separate account?" },
    q7322: { h: "7b188ab211f6", text: "A queue to stop the pushing and shoving of the crowd while giving out relief: will you keep this queue rule?" },
    q7323: { h: "5d3a3291603a", text: "Giving work tools to villagers only after a safety lesson: would you enjoy this ritual of the lesson?" },
    q7324: { h: "fdd6c4f64199", text: "Not spreading a claim without checking the aid figures: does this firmness on checking appeal to you?" },
    q7325: { h: "0fbb3b4aae58", text: "Never letting the way out get blocked in a gathering: would you keep up keeping the way open?" },
    q7326: { h: "c3c4a2f3fb9b", text: "A bucket of water ready near the flame of lamps and incense: would you accept this bucket rule?" },
    q7327: { h: "cc1502ec61ea", text: "Cutting the main power before washing the roller of the religious printing press: will you keep this cutting of power?" },
    q7328: { h: "4dcde9c3c5c4", text: "The extraction fan running amid the smell of strong cleaning chemicals: would you enjoy this habit of the fan?" },
    q7329: { h: "1ed2385d1450", text: "Sterilising scissors and razor after every customer: does this ritual of cleanliness appeal to you?" },
    q7330: { h: "3d3199a6f5e2", text: "A timer for the time limit and water in the hot steam room: would you keep up this timer rule?" },
    q7331: { h: "77b23a20817b", text: "Learning first the hold for handling an animal that bites: would you accept this lesson of the hold?" },
    q7332: { h: "dbdced3a0f94", text: "Putting a yellow warning board on a slippery floor: will you keep this habit of the board?" },
    q7333: { h: "4cc69b902001", text: "Switching off the mains before starting an electrical repair: would you enjoy this switching off?" },
    q7334: { h: "d3fc625f682f", text: "Keeping the exit routes of the stage open even in a crowd: does this open exit appeal to you?" },
    q7335: { h: "a92279a3a8bc", text: "Fireworks away from the crowd, with a bucket of water kept near: would you keep up this rule of distance and bucket?" },
    q7336: { h: "9284e5507ffd", text: "Dry wood and a ring of distance around the funeral pyre: would you accept this ring of distance?" },
    q7337: { h: "1464c9b06641", text: "An anti-slip mat and a grab bar in an elderly person's bathroom: will you keep this arrangement of grips?" },
    q7338: { h: "f72ad20b4f7c", text: "Testing the pipe of the gas stove for leaks with soap foam every day: would you enjoy this foam test?" },
    q7339: { h: "7b4f34b959b9", text: "Thick gloves against the sharp glass and needles hidden in scrap: does this glove rule appeal to you?" },
    q7340: { h: "00fc15d974ce", text: "Holding hot iron with tongs, never with bare hands: would you keep up this rule of tongs?" },
    q7341: { h: "34e63d90e583", text: "Turning the face away when opening the scorching door of the potter's kiln: would you accept this turning of the face?" },
    q7342: { h: "59424152e9ad", text: "A thumb guard cap to avoid the prick of the leather needle: will you keep this habit of the cap?" },
    q7343: { h: "5ad27c5103ff", text: "Wiping up any slippery patch at once near the hot-water boiler: would you enjoy this habit of wiping?" },
    q7344: { h: "f5a61a2000d0", text: "Changing or sterilising the razor after every customer: does this ritual of changing appeal to you?" },
    q7345: { h: "12521029cda3", text: "Not ending up asking for anyone's secret code in a pawn transaction: would you keep up this restraint in asking?" },
    q7346: { h: "8b62db690eb8", text: "A loose scarf must not get caught in the turning wheel of the spinning wheel: would you accept this alertness about dress?" },
    q7347: { h: "ba6429d87de5", text: "Air from an open window in the room with paints and chemicals: will you keep this air rule?" },
